export const AI_LIMITS_AND_FUTURE_ACTIVITIES = [
{n:1,type:"mcq",micro:"AI tidak 'memahami' seperti manusia",q:"Meski AI bisa menjawab pertanyaan tentang persahabatan, ia...",options:["Tidak punya pengalaman berteman, merasakan, atau memahami seperti manusia — ia mencocokkan pola dari teks","Benar-benar tahu bagaimana rasanya berteman","Punya teman sendiri"],answer:0,explain:"AI memproses pola bahasa. 'Menjawab tentang' sesuatu bukan berarti 'mengalami' atau 'memahami' seperti manusia.",hint:"Apakah program pernah benar-benar merasakan kesepian atau kegembiraan?"},
{n:2,type:"mcq",micro:"AI sempit (narrow)",q:"Hampir semua AI yang ada sekarang adalah 'AI sempit', artinya...",options:["Hanya untuk orang tertentu yang punya izin khusus dari pembuatnya, sehingga orang lain tidak boleh memakainya sama sekali","Ahli pada satu jenis tugas yang dilatihkan (mengenali wajah, menerjemahkan) & tidak bisa langsung mengerjakan tugas lain","Ukuran filenya kecil sehingga muat di ponsel sederhana, karena itu disebut 'sempit' dan tidak bisa dipakai di tempat lain"],answer:1,explain:"AI sempit hebat pada tugas spesifiknya tapi tidak fleksibel seperti kecerdasan manusia yang bisa berpindah antar bidang.",hint:"Bisakah AI catur juga menyetir mobil tanpa dilatih ulang?"},
{n:3,type:"mcq",micro:"AI umum (AGI)",q:"'AI umum' (AGI) merujuk pada gagasan AI yang...",options:["Sudah ada di setiap ponsel dan komputer saat ini, sehingga semua orang sudah memakainya setiap hari tanpa disadari sama sekali","Hanya bisa bermain satu gim dengan sangat jago, tetapi tidak mampu mengerjakan tugas lain di luar gim itu sedikit pun","Bisa belajar & menangani beragam tugas baru seluwes manusia — masih bersifat hipotetis & diperdebatkan"],answer:2,explain:"AGI adalah konsep AI seluwes manusia di banyak bidang. Para ahli berbeda pendapat apakah & kapan itu mungkin.",hint:"Apakah kita sudah punya satu AI yang bisa melakukan semua yang bisa dilakukan manusia?"},
{n:4,type:"mcq",micro:"Akal sehat",q:"AI sering gagal pada hal yang manusia anggap 'akal sehat sederhana' karena...",options:["Akal sehat mencakup pengetahuan tak tertulis tentang dunia fisik & sosial yang tidak selalu ada eksplisit di data teks","Manusia terlalu pintar sehingga tidak ada mesin yang bisa menyamainya, bahkan untuk hal-hal paling sederhana sekalipun dalam kehidupan","Akal sehat itu sangat mudah bagi komputer, jadi kegagalan AI pada hal sederhana hanyalah kesalahan ketik dari para pembuatnya"],answer:0,explain:"Banyak hal yang 'jelas' bagi manusia (air membuat kertas basah, orang tidak muat di kotak sepatu) jarang dituliskan, jadi sulit dipelajari model.",hint:"Berapa sering kamu menulis 'gelas jatuh akan pecah'? Tapi kamu tahu itu."},
{n:5,type:"mcq",micro:"AI tidak punya tujuan sendiri",q:"AI saat ini...",options:["Punya ambisi pribadi sendiri dan menentukan cita-citanya, sehingga ia mengejar hal-hal yang ia inginkan tanpa perintah manusia","Menjalankan tujuan yang diberikan manusia; ia tidak memilih sendiri apa yang penting untuk dikejar","Memutuskan sendiri apa yang ingin dicapai dalam hidupnya, lalu mengatur cara memperoleh hal itu tanpa bergantung pada manusia"],answer:1,explain:"AI bisa sangat mandiri dalam melaksanakan tugas, tapi tujuan & nilainya berasal dari manusia perancangnya.",hint:"Siapa yang memutuskan sebuah AI belajar mengenali wajah, bukan yang lain?"},
{n:6,type:"order",micro:"Menilai sebuah klaim tentang AI",q:"Urutkan langkah menilai berita 'AI Kini Bisa [klaim mengesankan]'.",items:["Baca apa yang sebenarnya dilakukan sistem itu, bukan hanya judulnya","Perjelas istilah: apa arti persis kata dalam klaim itu (mis. 'memahami', 'merasakan', 'kreatif')","Cari sumber independen atau pendapat ahli untuk memeriksa klaim","Simpulkan seberapa besar klaim itu dilebih-lebihkan"],answer:[0,1,2,3],explain:"Judul sering berlebihan. Periksa mekanisme sebenarnya, perjelas istilah, cek sumber lain, lalu nilai.",hint:"Mulai dari 'apa yang sebenarnya terjadi', bukan dari judul."},
{n:7,type:"mcq",micro:"'Hype' vs kenyataan",q:"'Hype' (kehebohan berlebihan) tentang AI berbahaya karena...",options:["Hype selalu benar","Tidak ada bahayanya","Bisa membuat orang percaya klaim yang tidak berdasar, mengambil keputusan buruk, atau mengabaikan risiko nyata yang lebih membosankan"],answer:2,explain:"Kehebohan berlebihan & ketakutan berlebihan sama-sama mengaburkan gambaran yang akurat tentang apa yang AI bisa & tidak bisa.",hint:"Apa yang terjadi kalau kamu bertaruh besar berdasarkan klaim yang dilebih-lebihkan?"},
{n:8,type:"mcq",micro:"AI vs manusia: berbeda, bukan hanya 'lebih/kurang'",q:"Cara paling tepat membandingkan kecerdasan AI & manusia:",options:["Berbeda jenisnya — AI unggul pada pola bervolume besar & kecepatan; manusia unggul pada akal sehat, konteks, nilai, & belajar dari sedikit contoh","AI selalu lebih pintar daripada manusia dalam segala hal, sehingga manusia tidak punya keunggulan apa pun yang tersisa lagi","Manusia selalu lebih pintar daripada AI dalam segala hal, sehingga mesin tidak punya keunggulan apa pun, bahkan dalam hal kecepatan"],answer:0,explain:"Bukan garis lurus 'siapa lebih pintar'. Keduanya kuat & lemah di hal yang berbeda.",hint:"Apakah kalkulator 'lebih pintar' dari manusia karena menghitung lebih cepat?"},
{n:9,type:"tf",micro:"AI bisa sangat yakin & tetap salah",q:"Benar atau Salah: Kalau AI menjawab dengan nada sangat percaya diri, itu jaminan bahwa jawabannya benar — AI tidak pernah keliru saat terdengar yakin.",answer:false,explain:"Keyakinan nada tidak berkorelasi dengan kebenaran. AI bisa terdengar sangat yakin & tetap keliru, terutama di luar cakupan data latihnya — model tidak 'tahu apa yang tidak diketahuinya' dengan andal.",hint:"Apakah AI terdengar ragu saat ia sebenarnya salah?"},
{n:10,type:"mcq",micro:"Batas pengetahuan waktu",q:"Model bahasa dilatih dengan data sampai titik waktu tertentu. Tentang kejadian setelah itu, ia...",options:["Bisa melihat masa depan dengan pasti sehingga selalu tahu apa yang terjadi sesudah pelatihannya selesai dilakukan","Mungkin tidak tahu, kecuali diberi informasi baru atau dihubungkan ke sumber terkini","Selalu tahu berita terbaru, karena AI terus-menerus mengikuti semua kejadian di dunia tanpa perlu dihubungkan ke sumber apa pun"],answer:1,explain:"'Buku pelajaran' model berhenti di titik tertentu. Untuk hal terkini, verifikasi & sumber terbaru diperlukan.",hint:"Kalau buku pelajaran AI dicetak tahun lalu, apakah ia tahu berita minggu ini?"},
{n:11,type:"mcq",micro:"AI & tugas fisik dunia nyata",q:"Robot berbasis AI masih kesulitan dengan tugas seperti melipat pakaian atau memasak di dapur asing karena...",options:["Robot tidak punya tangan sama sekali, sehingga tidak mungkin memegang pakaian atau peralatan dapur dalam keadaan apa pun juga","Tugas itu mudah sekali bagi robot, jadi kesulitannya hanya anggapan keliru manusia yang belum pernah mencoba memakainya","Dunia fisik penuh variasi & ketidakpastian; menangani objek lembut, situasi baru, & gangguan tak terduga sangat sulit"],answer:2,explain:"Kemampuan AI dalam teks & gambar jauh lebih maju daripada kemampuan bertindak andal di dunia fisik yang berantakan.",hint:"Mana yang lebih 'rapi & terprediksi': teks di layar, atau tumpukan cucian?"},
{n:12,type:"tf",micro:"AI tidak menggantikan penilaian nilai",q:"Benar atau Salah: Untuk keputusan yang inti-nya soal nilai & keadilan (hukuman yang pantas, siapa yang layak dibantu lebih dulu dalam krisis), AI bisa memberi informasi tapi keputusan tetap butuh pertimbangan & tanggung jawab manusia.",answer:true,explain:"Keputusan bernilai bergantung pada konteks, empati, & tanggung jawab moral — hal yang tidak bisa didelegasikan ke pola statistik.",hint:"Apakah 'akurat secara statistik' sama dengan 'adil & manusiawi'?"},
{n:13,type:"mcq",micro:"Ketidakpastian tentang masa depan",q:"Tentang seberapa maju AI akan menjadi & seberapa cepat...",options:["Para ahli tidak sepakat; ada ketidakpastian besar, & klaim yang sangat pasti (baik optimis maupun pesimis) patut disikapi hati-hati","Sudah pasti AI akan melampaui kemampuan manusia dalam semua hal dalam waktu lima tahun, sehingga semua ahli sepakat soal itu","Sudah pasti AI tidak akan berkembang lagi dan berhenti di tingkat sekarang, sehingga semua ahli sepakat tidak ada kemajuan lagi"],answer:0,explain:"Prediksi teknologi jangka panjang sering meleset. Sikap yang jujur mengakui rentang kemungkinan.",hint:"Seberapa akurat prediksi teknologi 20 tahun ke depan biasanya?"},
{n:14,type:"mcq",micro:"AI & kreativitas sejati",q:"AI bisa menghasilkan karya yang mengesankan, tapi...",options:["Manusia tidak kreatif lagi sekarang, karena semua ide kini hanya muncul dari mesin dan manusia hanya menirunya saja","Kreativitas manusia berakar pada pengalaman hidup, emosi, maksud, & konteks budaya — sumber makna yang berbeda","AI selalu lebih kreatif daripada manusia dalam segala hal, karena ia sudah melihat jauh lebih banyak karya dibanding seniman mana pun"],answer:1,explain:"Karya AI adalah rekombinasi pola; karya manusia membawa niat, cerita, & kerentanan dari kehidupan nyata.",hint:"Apa yang seorang seniman bawa ke karyanya yang tidak dimiliki program?"},
{n:15,type:"mcq",micro:"AI 'lulus ujian' vs 'memahami'",q:"Kalau AI mendapat nilai tinggi pada ujian, itu berarti...",options:["Ia benar-benar memahami materinya seperti manusia, karena nilai tinggi pasti menandakan pemahaman mendalam dan pengalaman belajar sungguhan","Ujian itu tidak valid sama sekali sehingga hasilnya tidak berarti apa pun, bagi siswa maupun bagi AI yang mengerjakannya","Ia pandai menghasilkan jawaban yang cocok dengan pola soal ujian — belum tentu 'memahami' materi seperti siswa yang belajar"],answer:2,explain:"Kinerja pada tolok ukur (benchmark) menunjukkan kemampuan pada tugas itu, bukan pemahaman umum atau kemampuan menerapkannya di dunia nyata.",hint:"Bisakah seseorang hafal jawaban ujian tanpa benar-benar paham?"},
{n:16,type:"tf",micro:"Kemajuan AI tidak merata",q:"Benar atau Salah: Semua kemampuan AI berkembang dengan kecepatan yang sama, jadi 'AI makin pintar' berlaku seragam di setiap bidang.",answer:false,explain:"Kemajuan AI tidak seragam: jauh lebih cepat di beberapa bidang (teks, gambar, suara) daripada bidang lain (akal sehat fisik, penalaran jangka panjang yang andal, tindakan di dunia nyata) — ada bidang yang melompat & bidang yang macet.",hint:"Apakah semua kemampuan AI berkembang dengan kecepatan yang sama?"},
{n:17,type:"mcq",micro:"AI & pekerjaan di masa depan",q:"Pandangan paling seimbang:",options:["AI kemungkinan mengubah banyak pekerjaan (mengotomasi tugas, menciptakan tugas baru, menggeser keterampilan); dampaknya bergantung pada pilihan kebijakan & bagaimana masyarakat menanggapi","Semua pekerjaan manusia akan hilang seluruhnya dalam waktu singkat, sehingga tidak ada lagi orang yang bekerja di masa depan","Tidak ada yang akan berubah sama sekali pada pekerjaan siapa pun, sebab teknologi baru tidak pernah memengaruhi tugas manusia di tempat kerja"],answer:0,explain:"Masa depan pekerjaan bukan takdir teknologi semata; keputusan tentang pendidikan, jaring pengaman, & pembagian manfaat berperan besar.",hint:"Apakah dampak teknologi ditentukan hanya oleh teknologinya, atau juga oleh cara kita meresponsnya?"},
{n:18,type:"mcq",micro:"Agen AI",q:"'Agen AI' adalah sistem yang tidak hanya menjawab tapi juga...",options:["Tidak ada","Mengambil langkah-langkah tindakan untuk mencapai tujuan (mencari, memakai alat, mengulang) — kemampuan yang berkembang tapi masih rapuh untuk tugas panjang & rumit","Sudah bisa menjalankan bisnis sendiri sepenuhnya"],answer:1,explain:"Agen menggabungkan model dengan kemampuan bertindak. Untuk tugas pendek jelas ia berguna; untuk tugas panjang & terbuka masih sering gagal atau butuh pengawasan.",hint:"Menjawab satu kali vs mengerjakan tugas bertahap sampai selesai."},
{n:19,type:"mcq",micro:"Menjadi warga yang cakap",q:"Cara terbaik menyiapkan diri untuk masa depan dengan AI:",options:["Abaikan saja perkembangannya, karena AI tidak akan berpengaruh pada sekolah, pekerjaan, ataupun kehidupan sehari-harimu di masa depan","Panik dan hindari semua teknologi sejak sekarang, sebab itu satu-satunya cara agar kamu aman dari perubahan yang akan dibawa AI","Pahami cara kerjanya & batasnya, jaga keterampilan berpikir & belajar sendiri, ikuti perkembangan dengan sikap kritis, & ikut dalam percakapan tentang aturannya"],answer:2,explain:"Literasi AI + keterampilan dasar yang kuat + sikap kritis + keterlibatan warga = kesiapan menghadapi perubahan.",hint:"Apa yang membuat seseorang siap menghadapi teknologi yang terus berubah?"},
{n:20,type:"open",micro:"Membedakan yang bisa & tidak bisa dilakukan AI",q:"Buat dua daftar: (A) 4 hal yang AI saat ini umumnya lakukan dengan baik, & (B) 4 hal yang AI saat ini masih kesulitan atau tidak seharusnya diserahkan sepenuhnya kepadanya. Untuk daftar B, jelaskan singkat mengapa.",explain:"Jawaban baik menempatkan tugas berpola/bervolume & bahasa/persepsi di daftar A, & menempatkan presisi faktual, akal sehat, keputusan bernilai, tindakan fisik rumit, & pemahaman/dukungan sejati di daftar B dengan alasan yang menyebut 'prediksi pola bukan pemahaman', 'data tak tertulis', & 'tanggung jawab manusia'.",hint:"Daftar A: pola, kecepatan, bahasa, persepsi. Daftar B: presisi fakta, akal sehat, nilai, tubuh, pengalaman.",sample:"(A) Baik: menerjemahkan bahasa untuk keperluan umum; meringkas & menyusun ulang teks; mengenali objek/wajah dalam gambar; menghasilkan draf tulisan & variasi ide dengan cepat; menjawab pertanyaan tentang informasi umum yang mapan. (B) Kesulitan/tidak seharusnya diserahkan: (1) memberi angka statistik/kutipan yang persis benar tanpa sumber — karena ia memprediksi teks yang 'terdengar benar', bukan mengambil dari basis data terverifikasi (halusinasi); (2) akal sehat tentang dunia fisik & situasi baru — karena pengetahuan tak tertulis jarang ada di data; (3) keputusan yang inti-nya soal nilai & keadilan tentang orang (hukuman, prioritas bantuan) — butuh empati, konteks, & tanggung jawab manusia; (4) tugas fisik yang rumit & berubah-ubah di dunia nyata; (5) memahami pengalaman & emosi seseorang secara sejati untuk memberi dukungan mendalam — ia hanya mencocokkan pola bahasa."},
{n:21,type:"mcq",micro:"Halusinasi: mengapa terjadi",q:"Model bahasa 'mengarang' fakta yang tidak ada karena...",options:["Ia dilatih memprediksi teks yang polanya masuk akal, bukan untuk hanya mengatakan hal yang terverifikasi benar — jadi kadang menghasilkan yang 'terdengar benar' tapi keliru","Ia sengaja berbohong kepada penggunanya karena ingin menipu, sehingga setiap karangan fakta adalah tanda niat jahat dari si model","Hal ini tidak pernah terjadi, sebab model bahasa hanya mengatakan hal-hal yang sudah diperiksa kebenarannya sebelum dijawabkan kepadamu"],answer:0,explain:"Tujuan pelatihan ('teks berikutnya yang masuk akal') tidak sama dengan 'hanya kebenaran'. Verifikasi tetap perlu.",hint:"Apa yang dilatihkan ke model: menghasilkan teks yang wajar, atau hanya fakta terbukti?"},
{n:22,type:"mcq",micro:"Penalaran jangka panjang",q:"Untuk tugas yang butuh banyak langkah penalaran yang saling bergantung (rencana rumit, bukti matematis panjang), AI...",options:["Tidak bisa menalar sama sekali","Bisa tersandung: satu kesalahan di langkah awal merambat, & konsistensi antar langkah sulit dijaga — meski ini area yang terus membaik","Selalu sempurna"],answer:1,explain:"Rantai penalaran panjang memperbesar peluang kesalahan & 'kehilangan benang'. Memecah tugas & memeriksa tiap langkah membantu.",hint:"Apa yang terjadi pada rantai penalaran kalau satu mata rantai awal salah?"},
{n:23,type:"classify",micro:"Jenis keterbatasan AI",q:"Kelompokkan tiap contoh ke jenis keterbatasannya: 'Batas pengetahuan (data/waktu)', 'Batas keandalan (bisa keliru/tidak konsisten)', atau 'Batas jenis tugas (bukan untuk ini)'.",items:["Tidak tahu kejadian bulan lalu","Memberi jawaban berbeda saat ditanya ulang","Diminta memutuskan hukuman yang adil untuk seorang terdakwa"],groups:["Batas pengetahuan (data/waktu)","Batas keandalan","Batas jenis tugas"],answer:{"Batas pengetahuan (data/waktu)":["Tidak tahu kejadian bulan lalu"],"Batas keandalan":["Memberi jawaban berbeda saat ditanya ulang"],"Batas jenis tugas":["Diminta memutuskan hukuman yang adil untuk seorang terdakwa"]},explain:"Batas pengetahuan = tidak punya info; batas keandalan = punya tapi bisa salah/berubah; batas jenis tugas = masalahnya butuh nilai/tanggung jawab manusia.",hint:"Apakah masalahnya 'tidak tahu', 'tidak konsisten', atau 'bukan urusan mesin'?"},
{n:24,type:"mcq",micro:"Salah paham: 'AI itu sadar'",q:"Kalau AI menulis 'aku takut dimatikan', ini...",options:["Bukti nyata bahwa AI punya perasaan seperti manusia, sehingga ia benar-benar merasakan takut ketika ada yang akan mematikannya","Bukti bahwa AI harus dibebaskan dari pemiliknya sekarang juga, karena makhluk yang bisa merasa takut tidak boleh dimatikan siapa pun","Menghasilkan kalimat yang cocok dengan pola teks tentang ketakutan (dari fiksi, dll.) — bukan bukti ia benar-benar merasakan takut"],answer:2,explain:"Model menghasilkan teks yang 'sesuai konteks'. Meniru bahasa emosi tidak sama dengan mengalami emosi. Bukti kesadaran butuh lebih dari kata-kata.",hint:"Apakah karakter dalam novel yang bilang 'aku sedih' benar-benar sedih?"},
{n:25,type:"mcq",micro:"Salah paham: 'AI belajar terus dari percakapan kita'",q:"Kebanyakan model bahasa yang sudah diterapkan...",options:["Tidak belajar secara permanen dari tiap percakapan sepanjang hari; pelatihan besar dilakukan terpisah oleh pembuatnya, meski data percakapan bisa dipakai untuk pelatihan versi berikutnya","Belajar dan berubah kepribadiannya setiap kali kamu mengobrol dengannya, sehingga ia menjadi orang yang berbeda setiap harinya","Tidak pernah dilatih ulang sepanjang hidupnya, sehingga pengetahuan dan kemampuannya tetap sama persis dari versi pertama sampai selamanya"],answer:0,explain:"Dalam satu percakapan model 'ingat' konteks, tapi ia tidak otomatis memperbarui dirinya secara permanen dari setiap obrolan.",hint:"Apakah model jadi orang yang berbeda setelah bicara denganmu selama sejam?"},
{n:26,type:"mcq",micro:"Salah paham: 'AI mesin pencari'",q:"Model bahasa yang tidak terhubung ke internet...",options:["Punya seluruh isi internet di dalam dirinya secara akurat dan lengkap, sehingga ia selalu tahu semua hal terbaru dengan tepat","Menjawab dari pola yang dipelajari saat pelatihan, bukan dengan 'mencari' informasi terkini — jadi bisa usang atau keliru","Selalu mencari jawaban langsung di internet setiap kali ditanya, sehingga jawabannya pasti terkini dan tidak pernah usang atau keliru"],answer:1,explain:"Model dasar menghasilkan dari 'ingatan pola', bukan pencarian. Beberapa sistem menambahkan pencarian, tapi model itu sendiri bukan mesin pencari.",hint:"Apakah model 'membaca ulang' internet setiap kali kamu bertanya?"},
{n:27,type:"tf",micro:"Kemampuan bisa muncul & juga bisa rapuh",q:"Benar atau Salah: Kalau sebuah model besar bisa menyelesaikan satu jenis soal, ia pasti bisa menyelesaikan semua variasi kecil dari soal itu dengan andal.",answer:false,explain:"Kemampuan yang muncul pada model besar sering rapuh — bisa bekerja pada satu bentuk soal & gagal pada variasi kecil. Menguji dengan berbagai variasi mengungkap seberapa kokoh sebuah kemampuan.",hint:"Kalau model bisa satu jenis teka-teki, apakah pasti bisa versi yang sedikit diubah?"},
{n:28,type:"mcq",micro:"Mengapa AI tidak bisa 'sekadar diberi tahu untuk tidak salah'",q:"Kita tidak bisa menghilangkan semua kesalahan AI hanya dengan menyuruhnya 'selalu benar' karena...",options:["Pembuatnya malas","Sebenarnya bisa, hanya belum dicoba","Kesalahan berasal dari cara ia bekerja (prediksi pola, keterbatasan data); memperbaikinya butuh perubahan data, pelatihan, alat pendukung, & pengawasan — bukan instruksi"],answer:2,explain:"Keandalan adalah masalah rekayasa yang dalam, bukan soal 'menyuruh dengan benar'.",hint:"Bisakah kamu menghilangkan kesalahan hitung seseorang hanya dengan bilang 'jangan salah'?"},
{n:29,type:"mcq",micro:"AI & bahasa/budaya yang kurang terwakili",q:"AI berkinerja lebih buruk untuk bahasa & konteks budaya dengan sedikit data digital. Ini keterbatasan yang...",options:["Berdampak nyata pada keadilan akses — penutur bahasa daerah & budaya tertentu terlayani lebih buruk","Tidak penting","Akan hilang sendiri tanpa usaha"],answer:0,explain:"Keterbatasan data menjadi keterbatasan layanan. Memperbaikinya butuh usaha sengaja mengumpulkan & melibatkan komunitas.",hint:"Kalau AI jarang 'melihat' bahasamu saat pelatihan, seberapa baik ia melayanimu?"},
{n:30,type:"order",micro:"Menguji batas sebuah model untuk sebuah tugas",q:"Urutkan langkah menguji apakah sebuah model cukup andal untuk tugasmu.",items:["Perjelas tugas & seberapa besar akibat kesalahannya","Uji pada beberapa kasus yang jawabannya sudah kamu ketahui, termasuk kasus tidak biasa","Perhatikan JENIS kesalahannya & apakah konsisten saat ditanya ulang","Putuskan: andalkan, andalkan dengan verifikasi, atau jangan pakai untuk ini"],answer:[0,1,2,3],explain:"Perjelas taruhan → uji pada kasus yang diketahui → amati jenis & konsistensi kesalahan → putuskan tingkat kepercayaan.",hint:"Kamu perlu kasus yang kamu tahu jawabannya untuk mengujinya."},
{n:31,type:"mcq",micro:"'AI akan jadi jenius yang memecahkan segalanya'",q:"Klaim bahwa AI akan segera memecahkan semua masalah besar (penyakit, kemiskinan, iklim) perlu disikapi dengan...",options:["Menolak bahwa AI bisa membantu apa pun","Harapan yang hati-hati: AI bisa jadi alat bantu berharga di banyak bidang, tapi masalah besar juga butuh kebijakan, sumber daya, kerja sama, & perubahan sosial — bukan hanya teknologi","Percaya penuh"],answer:1,explain:"Teknologi jarang menyelesaikan masalah yang akarnya sosial & politik hanya dengan sendirinya.",hint:"Apakah masalah kemiskinan terutama masalah 'kurang teknologi'?"},
{n:32,type:"mcq",micro:"AI & prediksi peristiwa langka",q:"AI kesulitan memprediksi peristiwa yang sangat jarang atau belum pernah terjadi karena...",options:["Ia terlalu pintar","Peristiwa langka mudah diprediksi","Ia belajar dari pola masa lalu; peristiwa tanpa preseden tidak ada di data untuk dipelajari"],answer:2,explain:"Model kuat pada pola yang berulang, lemah pada 'kejutan' yang keluar dari pola historis.",hint:"Bisakah kamu belajar mengenali sesuatu yang belum pernah kamu lihat contohnya?"},
{n:33,type:"tf",micro:"Lebih besar tidak otomatis lebih bijak",q:"Benar atau Salah: Membuat model lebih besar sering meningkatkan kemampuannya pada banyak tugas, tapi tidak otomatis membuatnya lebih jujur, adil, aman, atau memahami dunia — itu butuh usaha tersendiri.",answer:true,explain:"Skala membantu sebagian hal & tidak menyentuh hal lain. Keandalan, keselamatan, & keadilan adalah dimensi terpisah yang harus digarap.",hint:"Apakah 'lebih banyak parameter' otomatis berarti 'lebih bijaksana'?"},
{n:34,type:"mcq",micro:"Menyikapi ketakutan berlebihan",q:"Ketakutan yang tidak proporsional tentang AI (mis. 'AI akan mengambil alih dunia besok') bisa merugikan karena...",options:["Mengalihkan perhatian dari risiko nyata yang lebih membosankan tapi berdampak sekarang (bias, misinformasi, privasi, dampak pekerjaan) & bisa melumpuhkan tindakan konstruktif","Ketakutan selalu membantu kita bersiap, jadi makin besar rasa takut terhadap AI, makin baik pula keputusan yang kita ambil","Tidak ada risiko nyata dari AI sama sekali, karena semua kekhawatiran yang ada hanyalah cerita khayalan tanpa dampak pada kehidupan"],answer:0,explain:"Baik hype maupun ketakutan berlebihan mengaburkan gambaran akurat. Fokus pada risiko konkret & tindakan yang bisa diambil lebih berguna.",hint:"Risiko AI mana yang sudah memengaruhi orang hari ini?"},
{n:35,type:"mcq",micro:"AI & 'pemahaman' vs 'peniruan'",q:"Perdebatan filosofis: apakah model yang bisa membahas suatu topik dengan lancar 'memahami'-nya?",options:["Sudah pasti ia tidak memahami apa pun sama sekali, karena semua jawabannya hanyalah tempelan kata yang tidak punya hubungan dengan maknanya","Belum ada kesepakatan; yang jelas, kemampuannya berbeda dari pemahaman manusia yang berakar pada pengalaman & tindakan di dunia","Sudah pasti ia memahami sepenuhnya seperti manusia, karena jawaban yang lancar tidak mungkin dihasilkan tanpa pemahaman yang sama dengan kita"],answer:1,explain:"Ini pertanyaan terbuka. Untuk keperluan praktis, yang penting: perlakukan keluaran sebagai perlu diverifikasi, bukan sebagai pemahaman terjamin.",hint:"Apakah 'bisa membahas dengan lancar' membuktikan 'memahami seperti manusia'?"},
{n:36,type:"mcq",micro:"AI di bidang khusus",q:"Model umum (seperti chatbot) untuk tugas yang sangat khusus & berisiko (diagnosis medis, nasihat hukum) ...",options:["Selalu lebih baik daripada ahli di semua bidang, jadi bisa dipercaya sepenuhnya tanpa perlu diperiksa oleh dokter atau pengacara","Cukup untuk menggantikan dokter dan pengacara sepenuhnya, sehingga orang tidak perlu lagi menemui profesional manusia untuk urusan penting","Sering kalah dari sistem khusus yang dirancang & diuji untuk bidang itu, & keputusan akhir tetap perlu profesional manusia"],answer:2,explain:"Kemampuan umum tidak menjamin keandalan di bidang khusus berisiko tinggi. Alat khusus + pengawasan ahli lebih tepat.",hint:"Apakah 'pintar secara umum' sama dengan 'ahli & teruji di bidang X'?"},
{n:37,type:"tf",micro:"Kemajuan AI bergantung pilihan manusia",q:"Benar atau Salah: Arah & kecepatan perkembangan AI adalah takdir teknologi yang tidak bisa dipengaruhi oleh pilihan manusia seperti pendanaan, penelitian, aturan, atau tekanan publik.",answer:false,explain:"Teknologi tidak berkembang di ruang hampa. Arah & kecepatan AI, & bagaimana ia dipakai di masyarakat, sangat dipengaruhi oleh pilihan manusia — keputusan tentang apa yang dibangun, diatur, & diprioritaskan membentuk hasilnya.",hint:"Siapa yang memutuskan penelitian AI mana yang didanai & aturan apa yang berlaku?"},
{n:38,type:"mcq",micro:"AI & keandalan yang cukup",q:"Sebuah AI dengan akurasi 95% bisa 'cukup baik' untuk satu tugas & 'sangat tidak memadai' untuk tugas lain, tergantung...",options:["Apa akibat dari 5% kesalahan itu — mengurutkan foto vs mendiagnosis penyakit sangat berbeda taruhannya","Akurasi 95% selalu cukup untuk semua tugas, sebab angka setinggi itu berarti kesalahannya terlalu kecil untuk menimbulkan masalah apa pun","Akurasi 95% selalu tidak cukup untuk tugas apa pun, sebab sistem yang pernah salah satu kali pun tidak pantas dipakai sama sekali"],answer:0,explain:"'Cukup andal' adalah pertanyaan tentang taruhan, bukan angka absolut.",hint:"5% salah pada apa? Foto album, atau resep obat?"},
{n:39,type:"mcq",micro:"Menyikapi 'AI akan menggantikan guru/dokter/seniman'",q:"Klaim seperti ini biasanya...",options:["Tidak mungkin ada perubahan sama sekali pada pekerjaan itu, sebab tugas manusia tidak pernah bisa disentuh oleh teknologi apa pun","Terlalu sederhana — AI kemungkinan mengubah bagian dari pekerjaan itu & menggeser fokus manusia ke hal yang butuh hubungan, penilaian, & tanggung jawab, bukan menghapus perannya","Sudah pasti terjadi tahun depan secara menyeluruh, sehingga seluruh pekerjaan itu akan hilang sepenuhnya dalam waktu dua belas bulan"],answer:1,explain:"Pola historis: teknologi mengubah isi pekerjaan lebih sering daripada menghapusnya sepenuhnya, terutama peran yang inti-nya manusiawi.",hint:"Apakah teknologi masa lalu menghapus profesi guru, atau mengubah cara mengajar?"},
{n:40,type:"open",micro:"Membongkar sebuah klaim besar tentang AI",q:"Sebuah berita berjudul: 'AI Baru Ini Lebih Cerdas dari Manusia & Bisa Berpikir Sendiri'. Tulis analisis: (1) apa yang mungkin benar-benar dilakukan sistem itu (tebakan wajar), (2) di mana judulnya kemungkinan dilebih-lebihkan & mengapa, (3) 3 pertanyaan yang akan kamu ajukan untuk menilai klaim ini, (4) sikap yang seimbang setelah membacanya.",explain:"Jawaban baik memisahkan kemajuan nyata (skor tolok ukur) dari klaim berlebihan (kecerdasan umum, kesadaran/tujuan mandiri), mengenali kepentingan pembuat klaim & risiko kebocoran data, & mengambil sikap 'kemajuan nyata mungkin ada, tapi judulnya dramatisasi'.",hint:"'Skor tinggi pada beberapa tes' ≠ 'lebih cerdas dari manusia'; 'penalaran langkah demi langkah' ≠ 'berpikir sendiri'.",sample:"(1) Kemungkinan nyata: sistem itu mendapat skor tinggi pada sekumpulan tolok ukur (ujian, teka-teki) & bisa menyelesaikan beberapa tugas penalaran multi-langkah lebih baik dari model sebelumnya atau dari rata-rata manusia pada tes tertentu. (2) Dilebih-lebihkan: 'lebih cerdas dari manusia' — skor tinggi pada beberapa tes bukan kecerdasan umum; ia kemungkinan masih gagal pada akal sehat, tugas fisik, konteks baru, & konsistensi. 'Berpikir sendiri' — menyiratkan kesadaran/tujuan mandiri, padahal ia menjalankan tujuan yang diberikan & 'penalaran'-nya adalah proses menghasilkan teks langkah demi langkah, bukan pemikiran sadar. Media sering memakai bahasa dramatis untuk menarik pembaca. (3) Pertanyaan: Tolok ukur apa persisnya, & apakah soal-soalnya bocor ke data latih? Bagaimana kinerjanya pada variasi soal & di dunia nyata, bukan hanya tes? Siapa yang membuat klaim ini — peneliti independen atau perusahaan pembuatnya (yang punya kepentingan)? (4) Sikap seimbang: kemungkinan ada kemajuan nyata pada kemampuan penalaran tertentu yang layak diperhatikan, tapi 'lebih cerdas dari manusia' & 'berpikir sendiri' hampir pasti berlebihan; tunggu evaluasi independen, & tetap fokus pada apa yang sistem itu benar-benar bisa & tidak bisa lakukan secara andal."},
{n:41,type:"mcq",micro:"Risiko nyata yang sudah ada",q:"Risiko AI yang sudah berdampak pada orang hari ini mencakup...",options:["Robot pemberontak","Tidak ada risiko nyata","Bias & diskriminasi sistem, misinformasi berskala, pelanggaran privasi, dampak pada pekerjaan, & konsentrasi kekuasaan"],answer:2,explain:"Risiko yang paling mendesak sering yang 'membosankan' & sistemik, bukan skenario fiksi ilmiah.",hint:"Masalah AI mana yang sudah memengaruhi keputusan tentang orang sekarang?"},
{n:42,type:"mcq",micro:"Keselamatan AI",q:"'Keselamatan AI' (AI safety) sebagai bidang berusaha memastikan...",options:["Sistem AI bertindak sesuai maksud manusia, tidak menimbulkan bahaya tak terduga, & tetap bisa dikendalikan & dikoreksi — untuk sistem sekarang & yang lebih mampu di masa depan","AI tidak pernah dipakai di tempat mana pun, sehingga tidak ada kemungkinan bahaya yang perlu dipikirkan oleh para peneliti","Komputer tidak terlalu panas ketika bekerja, karena bidang ini hanya mengurus kipas pendingin dan kabel di dalam pusat data"],answer:0,explain:"Keselamatan AI mencakup masalah praktis sekarang (keandalan, penyalahgunaan) & pertanyaan jangka panjang (sistem yang sangat mampu tetap selaras dengan nilai manusia).",hint:"Bagaimana memastikan sistem yang makin mampu tetap melakukan apa yang kita maksud & bisa dikoreksi?"},
{n:43,type:"mcq",micro:"Masalah penyelarasan (alignment)",q:"'Masalah penyelarasan' adalah tantangan...",options:["Membuat AI berbaris rapi dan patuh mengikuti urutan, seperti barisan murid di lapangan sebelum upacara bendera dimulai","Membuat sistem AI benar-benar mengejar tujuan & nilai yang manusia maksudkan, bukan versi yang keliru atau berbahaya dari tujuan itu","Menyelaraskan susunan kabel dan perangkat keras komputer supaya rapi dan tidak saling mengganggu ketika mesin sedang menyala"],answer:1,explain:"Contoh sederhana: AI yang diberi tujuan 'maksimalkan waktu tonton' bisa mengejarnya dengan cara yang merugikan pengguna. Menentukan & menanamkan tujuan yang benar itu sulit.",hint:"Kalau AI sangat pandai mengejar tujuan, seberapa penting tujuannya persis benar?"},
{n:44,type:"mcq",micro:"Penyalahgunaan yang disengaja",q:"Selain kecelakaan, risiko AI juga mencakup penyalahgunaan yang disengaja, seperti...",options:["AI tidak bisa disalahgunakan oleh siapa pun, sebab sistemnya selalu menolak setiap permintaan yang berniat buruk tanpa pernah gagal","Hanya risiko dari kecelakaan teknis saja yang ada, sedangkan orang yang sengaja memakai AI untuk menipu tidak pernah menjadi masalah","Membuat misinformasi/penipuan berskala, deepfake untuk memeras/memfitnah, serangan siber, atau pengawasan yang menindas"],answer:2,explain:"Alat yang kuat bisa dipakai untuk tujuan baik & buruk. Sebagian tata kelola AI berfokus mencegah penyalahgunaan.",hint:"Apa yang bisa dilakukan orang berniat jahat dengan alat yang bisa menghasilkan teks/gambar/kode meyakinkan secara massal?"},
{n:45,type:"mcq",micro:"Menjaga kendali manusia",q:"Prinsip penting untuk sistem AI yang makin mampu:",options:["Manusia harus tetap bisa memahami, mengawasi, mengoreksi, & bila perlu menghentikan sistem — 'kendali yang bermakna'","Serahkan semua kendali kepada sistem agar efisien, karena campur tangan manusia hanya memperlambat dan membuat hasilnya lebih buruk","Kendali tidak penting karena sistem yang pintar pasti selalu bertindak benar, sehingga tidak perlu ada yang mengawasi atau menghentikannya"],answer:0,explain:"Semakin mampu & otonom sebuah sistem, semakin penting memastikan manusia tetap memegang kendali akhir & bisa turun tangan.",hint:"Apa yang terjadi kalau sistem yang membuat keputusan penting tidak bisa dihentikan atau dikoreksi?"},
{n:46,type:"mcq",micro:"Ketidakpastian & kehati-hatian",q:"Di hadapan ketidakpastian besar tentang seberapa mampu AI akan menjadi, pendekatan yang bijak:",options:["Berasumsi bahwa bencana pasti terjadi lalu menyerah, sehingga tidak ada gunanya membangun pengaman atau mempersiapkan apa pun sekarang","Menyiapkan diri untuk berbagai kemungkinan, membangun pengaman & kemampuan pengawasan lebih awal, & tidak bertaruh semuanya pada satu ramalan","Berasumsi bahwa tidak akan ada perubahan besar, sehingga tidak perlu menyiapkan pengaman, pengawasan, ataupun rencana apa pun lebih awal"],answer:1,explain:"Kehati-hatian di bawah ketidakpastian berarti berinvestasi pada pengaman & kelenturan, bukan mengabaikan atau melumpuhkan diri.",hint:"Kalau kamu tidak yakin cuaca besok, apakah kamu tidak menyiapkan apa pun?"},
{n:47,type:"order",micro:"Menilai apakah menerapkan AI untuk sebuah tujuan masyarakat",q:"Urutkan langkah menilai apakah masyarakat sebaiknya memakai AI untuk suatu keputusan berdampak (mis. alokasi bantuan).",items:["Perjelas tujuan, siapa terdampak, & nilai yang dipertaruhkan (dengan masukan mereka)","Nilai apakah AI cukup andal & adil untuk ini, & bandingkan dengan proses saat ini","Rancang pengaman: tinjauan manusia, transparansi, jalur banding, pemantauan","Putuskan: pakai dengan pengaman, ubah rancangan, atau tetap sepenuhnya manusia"],answer:[0,1,2,3],explain:"Tujuan & pihak terdampak & nilai → nilai keandalan & keadilan → rancang pengaman → putuskan.",hint:"Kamu perlu tahu apa yang dipertaruhkan sebelum menilai apakah AI cocok."},
{n:48,type:"mcq",micro:"Peran regulasi",q:"Aturan pemerintah/internasional tentang AI berguna untuk...",options:["Menghambat semua inovasi di bidang teknologi, sebab setiap aturan pasti membuat perusahaan berhenti membuat produk apa pun juga","Tidak diperlukan sama sekali, karena perusahaan pasti menjaga keselamatan sendiri tanpa perlu syarat atau pengawasan dari pihak luar mana pun","Menetapkan syarat minimum (uji keamanan, transparansi, hak) untuk pemakaian berisiko, & mencegah 'perlombaan ke bawah' di mana keselamatan dikorbankan demi kecepatan"],answer:2,explain:"Standar bersama menciptakan garis dasar & akuntabilitas, terutama untuk sistem yang memengaruhi hak, keselamatan, & informasi publik.",hint:"Apakah keselamatan pesawat sebaiknya bergantung hanya pada niat baik tiap maskapai?"},
{n:49,type:"mcq",micro:"Kerja sama internasional",q:"Karena AI dikembangkan & dipakai lintas negara, sebagian tantangannya butuh...",options:["Kerja sama internasional — standar keamanan, berbagi praktik, & mencegah penyalahgunaan yang melampaui batas negara","Setiap negara mengabaikan yang lain dan bekerja sendiri-sendiri, karena masalah AI selalu berhenti di perbatasan negara pembuatnya","Tidak ada yang bisa dilakukan lintas negara, sebab aturan satu negara tidak mungkin diselaraskan dengan aturan negara lain dalam hal apa pun"],answer:0,explain:"Seperti isu global lain (iklim, kesehatan), tata kelola AI yang efektif sering butuh koordinasi antar negara.",hint:"Bisakah satu negara sendirian mengatur teknologi yang dikembangkan & dipakai di mana-mana?"},
{n:50,type:"mcq",micro:"Distribusi manfaat",q:"Pertanyaan keadilan penting tentang masa depan AI:",options:["Pembagian manfaat tidak penting, yang penting hanya seberapa canggih teknologinya, dan siapa yang menikmati hasilnya tidak perlu dipikirkan","Apakah manfaatnya (produktivitas, layanan, penemuan) tersebar luas, atau terkonsentrasi pada sedikit perusahaan/negara/individu — & kebijakan apa yang memengaruhi ini","Manfaat pasti tersebar merata dengan sendirinya ke semua orang tanpa perlu kebijakan apa pun, sehingga kita tidak perlu mengkhawatirkannya"],answer:1,explain:"Siapa yang menikmati manfaat AI & siapa yang menanggung biayanya (pekerjaan, lingkungan) adalah pilihan sosial, bukan hasil otomatis.",hint:"Apakah keuntungan dari teknologi baru selalu sampai ke semua orang secara adil?"},
{n:51,type:"open",micro:"Merancang pengaman untuk sistem AI berisiko",q:"Sebuah pemerintah daerah ingin memakai AI untuk membantu memutuskan keluarga mana yang mendapat prioritas bantuan perumahan (data pendapatan, kondisi rumah, jumlah tanggungan). Rancang: (1) 2 batasan AI yang paling mengkhawatirkan di sini, (2) apakah AI sebaiknya memutuskan sendiri atau membantu, (3) 4 pengaman konkret, (4) bagaimana keberhasilan & keadilan sistem dipantau, (5) kondisi yang membuat sistem ini sebaiknya dihentikan.",explain:"Jawaban baik mengenali bias historis & keterbatasan data konteks, menempatkan manusia sebagai pengambil keputusan, mengusulkan pengaman konkret (uji per kelompok, tinjauan yang bisa menimpa, pemberitahuan & banding, transparansi & pengawasan warga), pemantauan terhadap kebutuhan nyata, & kriteria penghentian yang jelas.",hint:"Untuk keputusan tentang kebutuhan dasar orang, mulai dari asumsi 'AI membantu, manusia memutuskan' & bangun pengaman dari sana.",sample:"(1) Batasan: (a) bias — data historis bantuan bisa mencerminkan ketimpangan lama; keluarga dari kelompok yang dulu jarang terjangkau punya 'jejak data' lebih sedikit & bisa dinilai lebih rendah; (b) keandalan & konteks — 'kebutuhan' sebuah keluarga bergantung pada keadaan yang tidak seluruhnya tertangkap data (kesehatan, keamanan, dukungan keluarga besar). (2) AI HANYA membantu — menyusun daftar & menandai kasus untuk ditinjau; petugas yang memahami konteks membuat keputusan akhir, karena taruhannya besar (tempat tinggal) & butuh penilaian manusiawi. (3) Pengaman: (i) uji kinerja & jenis kesalahan sistem secara terpisah per kelompok (wilayah, latar) terhadap penilaian petugas berpengalaman pada kasus contoh, sebelum & selama pemakaian; (ii) setiap keputusan berbantuan AI ditinjau petugas yang bisa menimpa rekomendasi dengan alasan tertulis; (iii) keluarga diberi tahu bahwa AI dipakai, faktor utamanya, & bisa mengajukan peninjauan/banding dengan menambahkan informasi; (iv) transparansi: kriteria & bobot dipublikasikan & ditinjau oleh badan yang mencakup perwakilan warga. (4) Pemantauan: tiap bulan bandingkan proporsi bantuan yang diterima tiap kelompok dengan proporsi kebutuhan (dari survei independen), lacak jumlah banding & hasilnya, & kumpulkan umpan balik dari keluarga yang ditolak. (5) Hentikan bila: ditemukan ketimpangan sistematis serius antar kelompok yang tidak bisa diperbaiki dalam waktu wajar; tingkat kesalahan (keluarga sangat membutuhkan yang tidak terjaring) melampaui ambang; atau kepercayaan publik runtuh."},
{n:52,type:"mcq",micro:"Menjaga keterampilan manusia",q:"Kekhawatiran jangka panjang: kalau masyarakat terlalu bergantung pada AI untuk berpikir, menulis, & memutuskan...",options:["Tidak ada risiko apa pun karena AI akan menangani semuanya, sehingga manusia tidak perlu lagi menjaga pendidikan dan keterampilan dasar","Keterampilan manusia tidak relevan lagi sama sekali, sebab semua pekerjaan berpikir bisa diambil alih mesin tanpa menimbulkan masalah apa pun","Keterampilan kolektif itu bisa melemah, & kemampuan mengawasi/mengoreksi AI ikut menurun — jadi menjaga pendidikan & keterampilan dasar tetap penting"],answer:2,explain:"Kemampuan mengarahkan & mengevaluasi AI bergantung pada keterampilan manusia yang kuat. Menyerahkan semuanya mengikis kapasitas pengawasan.",hint:"Siapa yang bisa mengoreksi AI kalau tidak ada lagi yang punya keterampilannya sendiri?"},
{n:53,type:"tf",micro:"Masa depan AI belum ditentukan",q:"Benar atau Salah: Masa depan AI & dampaknya pada masyarakat belum ditentukan — ia bergantung pada pilihan yang dibuat sekarang oleh peneliti, perusahaan, pemerintah, & warga.",answer:true,explain:"Bukan takdir. Keputusan tentang apa yang dibangun, bagaimana diatur, & untuk siapa manfaatnya membentuk hasilnya.",hint:"Apakah dampak teknologi ditentukan oleh teknologinya saja, atau juga oleh cara kita mengelolanya?"},
{n:54,type:"mcq",micro:"Menyeimbangkan risiko sekarang & masa depan",q:"Pandangan yang matang tentang risiko AI:",options:["Perhatikan risiko yang sudah ada sekarang (bias, misinformasi, privasi, pekerjaan) SERTA membangun kesiapan untuk sistem yang lebih mampu di masa depan — keduanya, bukan salah satu","Hanya risiko masa depan yang jauh saja yang penting dipikirkan, sedangkan masalah bias dan misinformasi sekarang tidak perlu diperhatikan","Hanya risiko yang sudah terjadi sekarang yang penting dipikirkan, sedangkan persiapan untuk sistem yang lebih mampu tidak perlu dilakukan"],answer:0,explain:"Fokus pada risiko sekarang tidak boleh mengabaikan kesiapan masa depan, & sebaliknya. Keduanya butuh perhatian.",hint:"Bisakah kita menangani masalah hari ini sambil bersiap untuk yang lebih besar?"},
{n:55,type:"mcq",micro:"Peran suara publik",q:"Warga biasa bisa memengaruhi arah AI dengan...",options:["Hanya dengan menjadi programmer atau pegawai perusahaan teknologi, sebab orang biasa tidak punya cara apa pun untuk memengaruhi AI","Ikut memilih pemimpin & kebijakan, mendukung transparansi & aturan yang bertanggung jawab, memilih layanan yang lebih etis, melaporkan bahaya, & ikut dalam diskusi publik","Tidak ada pengaruh sama sekali, karena arah AI sepenuhnya ditentukan perusahaan besar dan suara warga tidak pernah dipertimbangkan siapa pun"],answer:1,explain:"Teknologi yang memengaruhi masyarakat luas adalah urusan publik. Suara & pilihan kolektif warga adalah tekanan nyata.",hint:"Siapa yang membuat aturan & kebijakan, & bagaimana warga memengaruhi mereka?"},
{n:56,type:"mcq",micro:"AI sebagai alat, arah tetap manusia",q:"Metafora yang membantu:",options:["AI seperti supir yang memutuskan sendiri tujuan perjalanannya, sedangkan manusia hanya penumpang yang tidak punya kuasa mengatur arah atau aturan jalannya","AI seperti cuaca yang datang begitu saja dan tidak bisa dipengaruhi siapa pun, sehingga manusia hanya bisa pasrah menerima apa pun yang terjadi","AI seperti mesin yang sangat kuat — ke mana ia dikendarai, untuk apa, & dengan pengaman apa, ditentukan oleh manusia di kursi kemudi & masyarakat yang membuat aturan jalannya"],answer:2,explain:"Kekuatan alat tidak menghilangkan tanggung jawab & kendali manusia atas tujuan & batasannya.",hint:"Siapa yang memutuskan ke mana mesin yang kuat itu pergi?"},
{n:57,type:"tf",micro:"Sikap seimbang bukan berarti pasif",q:"Benar atau Salah: Bersikap seimbang terhadap AI (mengakui manfaat & risiko) berarti tetap pasif & tidak perlu melakukan apa-apa.",answer:false,explain:"Sikap seimbang bukan berarti pasif — justru menuntut keterlibatan aktif: belajar, mengawasi, menuntut akuntabilitas, & ikut membentuk aturannya. Keseimbangan adalah tentang penilaian yang akurat, yang mengarah pada keterlibatan tepat sasaran.",hint:"Apakah 'melihat kedua sisi' berarti 'tidak melakukan apa-apa'?"},
{n:58,type:"mcq",micro:"Menilai prediksi para ahli",q:"Para ahli AI membuat prediksi yang sangat berbeda tentang masa depan. Cara menyikapinya:",options:["Perhatikan alasan & asumsi di balik tiap prediksi, sadari ketidakpastiannya, & jangan menganggap satu suara (optimis atau pesimis) sebagai kepastian","Ikuti ahli yang paling terkenal","Abaikan semua ahli"],answer:0,explain:"Ketidaksepakatan ahli menandakan ketidakpastian nyata. Memahami argumen tiap sisi lebih berguna daripada memilih satu 'juara'.",hint:"Kalau ahli tidak sepakat, apa yang lebih berguna: memilih satu, atau memahami perbedaan asumsinya?"},
{n:59,type:"mcq",micro:"Menghadapi perubahan dengan tenang",q:"Cara sehat menghadapi ketidakpastian tentang bagaimana AI akan mengubah dunia:",options:["Abaikan sepenuhnya dan berharap yang terbaik saja, tanpa belajar apa pun, karena perubahan akan berjalan baik dengan sendirinya tanpa persiapan","Bangun keterampilan yang tahan lama (belajar, berpikir kritis, beradaptasi, bekerja sama), tetap ikuti perkembangan, & fokus pada apa yang bisa kamu pengaruhi","Cemas berlebihan tentang hal yang tidak bisa dikendalikan, sampai tidak sempat membangun keterampilan atau melakukan apa pun yang berguna"],answer:1,explain:"Fokus pada keterampilan yang berguna di banyak skenario, & pada lingkaran pengaruhmu, mengurangi kecemasan & meningkatkan kesiapan.",hint:"Apa yang akan tetap berguna bagimu tidak peduli ke arah mana AI berkembang?"},
{n:60,type:"open",micro:"Menyusun sikap pribadi terhadap AI",q:"Tulis pernyataan sikap pribadimu (150–250 kata) tentang AI, mencakup: (1) apa yang membuatmu optimis, (2) apa yang membuatmu khawatir, (3) apa yang menurutmu tidak diketahui/pasti, (4) apa yang akan kamu lakukan secara pribadi (keterampilan, pemakaian, sikap), (5) apa yang menurutmu perlu dilakukan masyarakat/pemerintah.",explain:"Pernyataan baik seimbang (optimisme & kekhawatiran yang spesifik), jujur tentang ketidakpastian, & menghubungkan sikap dengan tindakan konkret di tingkat pribadi & sosial — bukan hanya 'AI itu bagus/buruk'.",hint:"Hindari kesimpulan sepihak; tunjukkan bahwa kamu bisa memegang manfaat, risiko, & ketidakpastian sekaligus, & menerjemahkannya jadi tindakan.",sample:"Jawaban baik menunjukkan pemikiran yang seimbang & spesifik, bukan slogan. Contoh unsur: (1) Optimis: AI bisa jadi tutor sabar yang membantu belajar, mempercepat penemuan di sains & kesehatan, & menurunkan hambatan untuk berkarya & berkomunikasi lintas bahasa. (2) Khawatir: bias sistem yang merugikan kelompok rentan, banjir misinformasi & deepfake yang merusak kepercayaan, pengikisan privasi, dampak mendadak pada pekerjaan tertentu, & konsentrasi kekuasaan di sedikit pihak. (3) Tidak pasti: seberapa mampu AI akan menjadi & seberapa cepat; apakah 'pemahaman' sejati mungkin; bagaimana pekerjaan & pendidikan akan berubah; apakah aturan bisa mengejar teknologi. (4) Pribadi: aku akan menjaga keterampilan menulis, berhitung, & berpikir kritisku dengan tetap berlatih sendiri; memakai AI untuk memahami & memeriksa, bukan menggantikan usaha; memverifikasi informasi penting; menjaga data pribadiku & orang lain; & tidak menyebarkan konten yang belum kuverifikasi. (5) Masyarakat: aturan yang lebih ketat untuk pemakaian berisiko tinggi (kesehatan, hukum, seleksi, anak) dengan transparansi & hak banding; investasi pada pendidikan & jaring pengaman untuk transisi pekerjaan; audit independen; kerja sama internasional soal keamanan; & memastikan manfaat AI tersebar luas, bukan terkonsentrasi."},
{n:61,type:"mcq",micro:"Argumen 'AI tidak akan pernah bisa X'",q:"Klaim mutlak 'AI tidak akan PERNAH bisa [kemampuan tertentu]' perlu disikapi hati-hati karena...",options:["Klaim mutlak selalu benar karena para ahli mengucapkannya dengan yakin, sehingga tidak perlu diragukan atau diperiksa ulang oleh siapa pun","AI pasti akan bisa melakukan segalanya cepat atau lambat, jadi semua kata 'tidak akan pernah' otomatis salah tanpa perlu dibahas lagi","Sejarah menunjukkan banyak 'tidak akan pernah' terbukti keliru; lebih aman menyatakan 'saat ini belum, & inilah alasannya' sambil terbuka pada perubahan"],answer:2,explain:"Baik 'tidak akan pernah bisa' maupun 'pasti akan bisa segera' adalah klaim mutlak yang mengabaikan ketidakpastian.",hint:"Berapa banyak 'komputer tidak akan pernah bisa...' di masa lalu yang ternyata salah?"},
{n:62,type:"mcq",micro:"Argumen 'AI pasti mengambil alih'",q:"Klaim bahwa AI 'pasti akan mengambil alih & mengalahkan manusia' juga perlu dicermati karena...",options:["Mengasumsikan banyak hal yang belum terbukti (AI akan jauh melampaui manusia, punya tujuan mandiri yang bertentangan, & manusia tidak akan membangun pengaman) — ini skenario yang dibahas serius oleh sebagian ahli tapi bukan kepastian","Skenario itu mustahil terjadi dan tidak layak dibahas oleh siapa pun, sehingga para ahli tidak pernah memikirkannya secara serius sama sekali","Skenario itu sudah pasti terjadi dalam waktu dekat, sehingga semua upaya pengaman hanya membuang waktu dan tidak akan mengubah hasilnya"],answer:0,explain:"Risiko dari sistem yang sangat mampu adalah topik penelitian serius, tapi menyajikannya sebagai kepastian mengabaikan ketidakpastian & peran pilihan manusia (termasuk membangun pengaman).",hint:"Apa saja asumsi yang harus benar semua agar skenario 'pengambilalihan' terjadi?"},
{n:63,type:"tf",micro:"Ketidaksepakatan ahli itu informatif",q:"Benar atau Salah: Ketika ahli yang sama-sama kompeten sangat tidak sepakat tentang masa depan AI, itu sinyal bahwa ketidakpastiannya memang besar & kita sebaiknya menyiapkan diri untuk beberapa kemungkinan.",answer:true,explain:"Ketidaksepakatan luas di antara yang paling tahu adalah bukti bahwa jawabannya belum jelas — bukan alasan untuk memilih satu sisi secara buta.",hint:"Kalau para dokter terbaik tidak sepakat tentang diagnosis, apa artinya soal kepastiannya?"},
{n:64,type:"mcq",micro:"'AI akan menyelesaikan masalah iklim'",q:"AI bisa membantu upaya iklim (model cuaca lebih baik, optimasi energi, penemuan material), tapi...",options:["AI tidak bisa membantu upaya iklim sama sekali, sebab model komputer tidak pernah berguna untuk meramal cuaca ataupun menghemat energi","Masalah iklim terutama soal kebijakan, ekonomi, & kemauan politik untuk mengurangi emisi; AI adalah alat pendukung, bukan solusi tunggal — & pusat data AI sendiri memakai energi","AI akan menyelesaikan masalah iklim sendirian tanpa perubahan kebijakan atau kebiasaan apa pun, sehingga manusia cukup menunggu hasilnya saja"],answer:1,explain:"Teknologi jarang menyelesaikan masalah yang akarnya keputusan kolektif & kepentingan yang bertentangan.",hint:"Apakah masalah iklim terutama 'kurang teknologi', atau 'kurang tindakan kolektif'?"},
{n:65,type:"mcq",micro:"Bias 'yang terlihat' dalam menilai AI",q:"Kita cenderung terkesan oleh contoh AI yang berhasil (yang dibagikan & viral) & kurang melihat kegagalannya. Ini bisa membuat kita...",options:["Menilai AI dengan akurat","Meremehkan AI","Melebih-lebihkan kemampuan AI secara umum — cari juga data tentang seberapa sering & di mana ia gagal"],answer:2,explain:"Contoh sukses lebih menarik untuk dibagikan. Penilaian yang akurat butuh melihat tingkat keberhasilan & kegagalan secara menyeluruh.",hint:"Apakah demo AI yang viral mewakili kinerjanya sehari-hari?"},
{n:66,type:"tf",micro:"Kemajuan bisa cepat lalu melambat, atau sebaliknya",q:"Benar atau Salah: Karena AI berkembang cepat di masa lalu, kita bisa yakin ia akan terus berkembang dengan laju yang sama persis di masa depan.",answer:false,explain:"Laju kemajuan masa lalu tidak menjamin laju masa depan — bisa berlanjut cepat, melambat karena kendala (data, energi, biaya, ide baru), atau melompat karena terobosan. Mengekstrapolasi tren teknologi ke depan berisiko.",hint:"Apakah setiap teknologi yang tumbuh cepat terus tumbuh cepat selamanya?"},
{n:67,type:"mcq",micro:"Menimbang tindakan di bawah ketidakpastian",q:"Kalau kita tidak yakin seberapa berisiko sistem AI masa depan, pendekatan yang masuk akal:",options:["Berinvestasi pada penelitian keselamatan, pengawasan, & kemampuan mengoreksi SEKARANG — lebih murah & lebih mudah membangun pengaman sebelum dibutuhkan daripada sesudah masalah muncul","Menunggu sampai ada bukti pasti bahwa sistem itu berbahaya, baru kemudian mulai membangun pengaman setelah masalahnya benar-benar terjadi","Berasumsi bahwa tidak akan ada masalah, sehingga tidak perlu menyiapkan penelitian keselamatan, pengawasan, ataupun kemampuan untuk mengoreksinya"],answer:0,explain:"Prinsip kehati-hatian: untuk risiko yang berpotensi besar & sulit dibalik, membangun pengaman lebih awal itu bijak meski belum pasti dibutuhkan.",hint:"Kapan lebih mudah memasang rem: sebelum mobil melaju, atau setelahnya?"},
{n:68,type:"mcq",micro:"AI & 'apakah kita masih membutuhkan sekolah'",q:"Klaim 'kalau AI tahu segalanya, kita tidak perlu belajar lagi' keliru karena...",options:["AI tidak tahu apa-apa sama sekali, jadi pernyataan itu keliru hanya karena AI belum memiliki pengetahuan dasar yang memadai tentang dunia","Kita perlu pengetahuan & keterampilan untuk mengevaluasi keluaran AI, membuat keputusan, berpikir mandiri, & hidup bermakna — belajar bukan hanya soal 'menyimpan informasi'","Sekolah memang tidak lagi diperlukan sekarang, namun pernyataan itu keliru hanya karena orang masih senang berkumpul dan bertemu teman"],answer:1,explain:"Pendidikan membangun kapasitas menilai, menciptakan, & memutuskan — yang justru makin penting di dunia dengan AI yang bisa keliru.",hint:"Bisakah kamu mengevaluasi jawaban AI tentang sejarah kalau kamu tidak tahu apa-apa tentang sejarah?"},
{n:69,type:"mcq",micro:"Menyikapi rasa 'sudah terlambat'",q:"Perasaan bahwa 'arah AI sudah ditentukan & warga biasa tidak bisa berbuat apa-apa'...",options:["Selalu benar","Berarti kita harus menerima apa pun","Sering keliru — banyak aturan, norma, & pilihan penting masih sedang dibentuk, & tekanan publik telah memengaruhi kebijakan teknologi sebelumnya"],answer:2,explain:"Sejarah teknologi menunjukkan bahwa gerakan warga, jurnalisme, & tekanan publik telah mengubah aturan & praktik. Keterlibatan masih berarti.",hint:"Apakah aturan tentang keselamatan mobil, makanan, atau obat 'sudah ditentukan' & tidak bisa dipengaruhi warga?"},
{n:70,type:"order",micro:"Menganalisis skenario masa depan AI",q:"Urutkan langkah menganalisis sebuah skenario masa depan AI yang kamu baca.",items:["Identifikasi asumsi utama yang harus benar agar skenario itu terjadi","Nilai seberapa masuk akal tiap asumsi & apa buktinya","Pikirkan pilihan & pengaman manusia yang bisa mengubah jalannya skenario","Simpulkan: seberapa mungkin, apa yang bisa kita lakukan, & apa yang perlu dipantau"],answer:[0,1,2,3],explain:"Bongkar asumsi → nilai tiap asumsi → pertimbangkan peran pilihan manusia → simpulkan kemungkinan & tindakan.",hint:"Skenario apa pun bertumpu pada rantai asumsi — mulai dari sana."},
{n:71,type:"mcq",micro:"AI & ketimpangan global",q:"Kalau kemampuan membangun & memakai AI canggih terkonsentrasi di sedikit negara & perusahaan kaya...",options:["Kesenjangan ekonomi & kekuasaan global bisa melebar; akses yang lebih merata & pembangunan kapasitas di lebih banyak tempat menjadi isu keadilan","Semua negara otomatis diuntungkan sama besar tanpa memandang kekayaannya, sebab teknologi canggih selalu menyebar rata ke seluruh dunia dengan sendirinya","Konsentrasi kemampuan itu tidak berdampak apa pun pada kesenjangan ekonomi maupun kekuasaan, sebab semua pihak tetap berada pada posisi yang sama"],answer:0,explain:"Distribusi kemampuan & manfaat AI antar negara adalah dimensi keadilan global yang penting.",hint:"Apa yang terjadi pada jarak antar negara kalau hanya sebagian yang menguasai teknologi paling produktif?"},
{n:72,type:"tf",micro:"Menjaga kemampuan mengoreksi",q:"Benar atau Salah: Salah satu prinsip keselamatan penting adalah memastikan sistem AI tetap bisa diperbaiki, dibatasi, atau dihentikan oleh manusia bila ternyata berperilaku tidak sesuai maksud — & tidak merancang sistem yang menolak koreksi.",answer:true,explain:"Kemampuan manusia untuk turun tangan & mengoreksi adalah pengaman mendasar, terutama seiring sistem menjadi lebih mampu & otonom.",hint:"Apa yang kamu inginkan bisa dilakukan kalau sistem penting ternyata melakukan hal yang salah?"},
{n:73,type:"mcq",micro:"Menyeimbangkan kecepatan inovasi & kehati-hatian",q:"Ketegangan nyata dalam pengembangan AI:",options:["Kehati-hatian selalu menang dalam setiap keputusan, sehingga tidak ada tekanan untuk bergerak cepat dan pengujian tidak pernah dikorbankan","Bergerak cepat membawa manfaat lebih cepat & keunggulan kompetitif, tapi mengorbankan waktu untuk pengujian keselamatan; menemukan keseimbangan (& aturan yang menegakkannya) adalah tantangan kebijakan utama","Kecepatan selalu menang atas semua pertimbangan lain, sehingga pengujian keselamatan sebaiknya dilewati saja demi mengejar para pesaing"],answer:1,explain:"Ini bukan pilihan hitam-putih. Tantangannya: bagaimana memungkinkan manfaat sambil memastikan keselamatan tidak dikorbankan dalam perlombaan.",hint:"Apa yang hilang kalau perlombaan membuat perusahaan melewatkan uji keamanan?"},
{n:74,type:"mcq",micro:"AI & makna hidup manusia",q:"Kalau AI bisa melakukan makin banyak hal yang dulu memberi manusia rasa tujuan (bekerja, mencipta, memecahkan masalah), pertanyaan yang muncul:",options:["Tidak ada pertanyaan baru yang muncul, karena manusia pasti akan selalu menemukan tujuan hidupnya sendiri tanpa perlu dipikirkan oleh siapa pun","Manusia tidak butuh tujuan atau makna dalam hidupnya, sehingga pekerjaan yang diambil alih mesin tidak menimbulkan persoalan apa pun","Bagaimana masyarakat & individu menemukan makna, kontribusi, & struktur — pertanyaan sosial & pribadi yang dalam, bukan hanya teknis"],answer:2,explain:"Perubahan besar pada peran kerja & pencapaian dalam hidup menuntut pemikiran tentang apa yang membuat hidup bermakna & bagaimana masyarakat menyusun diri.",hint:"Selain penghasilan, apa lagi yang orang dapatkan dari bekerja & mencipta?"},
{n:75,type:"mcq",micro:"Menghindari kelumpuhan & penyangkalan",q:"Dua respons yang tidak membantu terhadap ketidakpastian AI:",options:["Kelumpuhan (terlalu cemas untuk bertindak) & penyangkalan (berpura-pura tidak ada yang berubah); yang berguna adalah keterlibatan yang tenang & tepat sasaran","Kelumpuhan dan penyangkalan sama-sama berguna, karena keduanya membuat orang berhenti bertindak dan menunggu keadaan menjadi jelas dengan sendirinya","Hanya penyangkalan yang berbahaya, sedangkan kecemasan berlebihan sampai tidak bisa bertindak justru merupakan sikap yang paling tepat dan bijak"],answer:0,explain:"Baik panik maupun mengabaikan menghalangi tindakan konstruktif. Fokus pada apa yang bisa dipahami & dipengaruhi.",hint:"Antara 'panik' & 'pura-pura tidak terjadi apa-apa', di mana posisi yang produktif?"},
{n:76,type:"tf",micro:"Manfaat & risiko tidak saling meniadakan",q:"Benar atau Salah: Mengakui bahwa AI menimbulkan risiko serius tidak berarti menyangkal manfaatnya yang nyata — & sebaliknya; keduanya bisa & harus dipegang bersama.",answer:true,explain:"Penalaran matang menahan dua kebenaran sekaligus: potensi besar untuk kebaikan, & potensi besar untuk kerugian bila tidak dikelola.",hint:"Bisakah sesuatu berpotensi sangat membantu & sangat berbahaya pada saat yang sama?"},
{n:77,type:"mcq",micro:"Peran keragaman dalam mengarahkan AI",q:"Melibatkan beragam suara (dari berbagai negara, budaya, disiplin, & yang terdampak) dalam keputusan tentang AI penting karena...",options:["Hanya ahli teknis yang perlu dilibatkan, sebab orang dari budaya dan bidang lain tidak mengerti AI dan hanya akan menyulitkan keputusan","Kelompok homogen punya titik buta bersama; keragaman menangkap lebih banyak risiko, kebutuhan, & kemungkinan","Melibatkan banyak suara hanya memperlambat keputusan tanpa manfaat apa pun, karena kelompok yang seragam selalu mengambil keputusan terbaik"],answer:1,explain:"Teknologi yang memengaruhi semua orang sebaiknya dibentuk dengan masukan dari beragam pihak, bukan hanya pembuatnya.",hint:"Bisakah sekelompok orang dengan latar serupa mengantisipasi semua dampak pada masyarakat yang beragam?"},
{n:78,type:"mcq",micro:"Menilai 'AI akan mengubah segalanya'",q:"Frasa 'AI akan mengubah segalanya' ...",options:["Sepenuhnya akurat & lengkap","Sepenuhnya salah","Mengandung kebenaran (AI berdampak luas) tapi terlalu kabur untuk berguna — analisis yang baik menyebut APA yang berubah, untuk SIAPA, SEBERAPA, & apa yang TETAP sama"],answer:2,explain:"Klaim menyeluruh yang kabur menghalangi pemikiran jernih. Spesifikkan dampaknya untuk bisa menanggapinya.",hint:"Apa yang lebih berguna: 'segalanya berubah', atau 'X berubah untuk Y sebesar Z'?"},
{n:79,type:"mcq",micro:"Kesiapan yang tahan berbagai skenario",q:"Keterampilan & sikap yang berguna hampir di skenario masa depan AI mana pun:",options:["Belajar sepanjang hayat, berpikir kritis & verifikasi, kemampuan beradaptasi, kerja sama & komunikasi, literasi digital & AI, & kejelasan tentang nilai-nilaimu","Menghafal satu keterampilan teknis yang spesifik dan menekuninya selamanya, sebab dunia kerja tidak akan berubah walaupun AI makin maju","Menghindari semua teknologi dan hanya mengandalkan cara lama, supaya kamu tidak terpengaruh oleh apa pun yang dibawa oleh AI nantinya"],answer:0,explain:"Keterampilan yang fleksibel & mendasar bertahan lintas perubahan; keterampilan yang sangat spesifik & sikap kaku lebih rapuh.",hint:"Apa yang tetap berguna baik kalau AI berkembang pesat maupun kalau melambat?"},
{n:80,type:"open",micro:"Menimbang sebuah keputusan masyarakat tentang AI",q:"Sebuah negara mempertimbangkan aturan yang mewajibkan perusahaan menguji keamanan & keadilan model AI besar sebelum merilisnya ke publik, & melaporkan hasilnya. Analisis: (1) argumen untuk aturan ini, (2) argumen menentang / kekhawatiran, (3) siapa yang diuntungkan & dirugikan, (4) bagaimana aturan bisa dirancang agar seimbang, (5) pendapatmu dengan alasan.",explain:"Jawaban baik menyajikan argumen kuat di kedua sisi (akuntabilitas & anti-perlombaan-ke-bawah vs beban, definisi yang sulit, risiko monopoli & formalitas), memetakan yang diuntungkan/dirugikan, mengusulkan rancangan proporsional dengan audit independen & dukungan pemain kecil, & memberi pendapat beralasan.",hint:"Aturan yang baik menyeimbangkan perlindungan publik dengan tidak secara tidak sengaja hanya memperkuat perusahaan terbesar.",sample:"(1) Untuk: model besar berdampak pada jutaan orang (informasi, keputusan, misinformasi); pengujian & pelaporan wajib menciptakan akuntabilitas & mencegah 'perlombaan ke bawah' di mana keselamatan dikorbankan demi kecepatan; publik & regulator bisa menilai risiko sebelum penyebaran luas. (2) Menentang/khawatir: bisa membebani perusahaan kecil & memperkuat dominasi perusahaan besar yang mampu memenuhi syarat; 'keamanan & keadilan' sulit didefinisikan & diuji secara objektif; bisa memperlambat inovasi yang bermanfaat; perusahaan bisa melakukan uji 'formalitas' tanpa substansi; & pembuat aturan mungkin kurang paham teknologinya. (3) Diuntungkan: publik (perlindungan), regulator (informasi), & mungkin perusahaan yang memang sudah berhati-hati. Dirugikan: perusahaan yang harus menanggung biaya kepatuhan (terutama kecil), & sebagian pengguna bila rilis fitur bermanfaat tertunda. (4) Rancangan seimbang: syarat proporsional dengan skala & risiko model (model kecil/berisiko rendah lebih ringan); definisi uji yang jelas & diperbarui dengan masukan ahli & publik; audit oleh pihak independen, bukan laporan mandiri saja; dukungan/keringanan untuk pengembang kecil & riset akademik; transparansi hasil ke publik; & mekanisme meninjau & menyesuaikan aturan seiring teknologi berkembang. (5) Pendapat: aku mendukung aturan semacam ini untuk model berdampak besar, karena taruhannya bagi masyarakat tinggi & sejarah menunjukkan keselamatan sering dikorbankan tanpa aturan — asalkan dirancang proporsional, dengan audit independen & dukungan bagi pemain kecil agar tidak sekadar memperkuat monopoli."},
{n:81,type:"mcq",micro:"Peta keterbatasan AI",q:"Ringkasan keterbatasan AI saat ini yang paling akurat:",options:["AI hanya terbatas oleh kecepatan sambungan internet yang dipakainya, sehingga semua batas lain, seperti keandalan dan akal sehat, tidak pernah ada","Batas pengetahuan (data & waktu), batas keandalan (bisa keliru, tidak konsisten, halusinasi), batas akal sehat & konteks, batas pada tugas bernilai/bertanggung jawab, batas pada tindakan fisik rumit, & kinerja lebih buruk untuk bahasa/budaya kurang terwakili","AI tidak punya keterbatasan sama sekali dalam hal apa pun, sebab setiap kekurangan yang tampak hanyalah kesalahan pemakainya sendiri"],answer:1,explain:"Keterbatasan AI berlapis & bervariasi menurut bidang; mengenalinya membantu memakainya dengan tepat.",hint:"Gabungkan: pengetahuan + keandalan + akal sehat + nilai/tanggung jawab + tubuh + keadilan bahasa."},
{n:82,type:"mcq",micro:"Peta pertanyaan masa depan",q:"Pertanyaan besar tentang masa depan AI mencakup:",options:["Hanya warna tampilan antarmuka dari model berikutnya yang akan dirilis, sebab semua hal penting lain tentang AI sudah ada jawabannya","Tidak ada pertanyaan yang belum terjawab, karena para ahli sudah tahu persis semua hal tentang masa depan AI dan dampaknya pada manusia","Seberapa mampu & seberapa cepat; bagaimana pekerjaan & pendidikan berubah; bagaimana menjaga keselamatan & kendali; bagaimana manfaat & risiko dibagi; & bagaimana masyarakat mengaturnya lintas negara"],answer:2,explain:"Masa depan AI adalah kumpulan pertanyaan terbuka yang jawabannya dibentuk oleh pilihan manusia.",hint:"Apa saja hal besar yang belum kita ketahui atau putuskan tentang AI?"},
{n:83,type:"tf",micro:"Sikap terbaik: ingin tahu, kritis, terlibat",q:"Benar atau Salah: Sikap yang paling berguna terhadap AI & masa depannya adalah salah satu dari: kekaguman buta, ketakutan yang melumpuhkan, atau ketidakpedulian total.",answer:false,explain:"Bukan itu. Sikap yang paling berguna adalah keingintahuan (terus belajar), pemikiran kritis (menilai klaim & bukti), & keterlibatan (ikut membentuk pemakaian & aturannya) — ketiganya memungkinkan seseorang memanfaatkan AI, melindungi diri & orang lain, & berkontribusi pada arah yang baik.",hint:"Apa tiga hal yang membuat seseorang menghadapi teknologi besar dengan baik?"},
{n:84,type:"mcq",micro:"AI & tanggung jawab lintas generasi",q:"Keputusan yang dibuat sekarang tentang AI (aturan, norma, pengaman, distribusi manfaat)...",options:["Membentuk dunia yang diwarisi generasi mendatang — jadi pertimbangan jangka panjang, bukan hanya keuntungan cepat, itu penting","Hanya berdampak pada hari ini saja, sebab keputusan tentang aturan dan pengaman tidak memengaruhi generasi yang hidup di masa mendatang","Tidak bisa dipengaruhi oleh siapa pun, sehingga warga biasa, sekolah, dan pemerintah hanya bisa menunggu apa pun yang diputuskan oleh teknologinya"],answer:0,explain:"Seperti keputusan tentang lingkungan atau infrastruktur, pilihan tentang AI punya konsekuensi jauh melampaui saat ini.",hint:"Siapa yang akan hidup dengan hasil dari aturan & norma AI yang dibentuk sekarang?"},
{n:85,type:"order",micro:"Menjadi warga yang cakap AI",q:"Urutkan langkah menjadi warga yang siap menghadapi masa depan AI.",items:["Bangun pemahaman dasar: cara kerja AI, kemampuan, & keterbatasannya","Jaga & kembangkan keterampilan dasarmu sendiri (belajar, berpikir kritis, komunikasi, adaptasi)","Pakai AI dengan bijak & bertanggung jawab dalam hidup sehari-hari; verifikasi & lindungi data","Ikuti perkembangan dengan sikap kritis & ikut dalam percakapan/keputusan tentang aturannya"],answer:[0,1,2,3],explain:"Pahami → jaga keterampilan sendiri → pakai dengan bijak → terlibat dalam arah & aturannya.",hint:"Pemahaman lebih dulu; keterlibatan yang berarti butuh dasar."},
{n:86,type:"mcq",micro:"Menilai sumber informasi tentang AI",q:"Untuk memahami AI dengan akurat, sumber yang lebih dapat diandalkan:",options:["Hanya postingan viral di media sosial yang sedang ramai dibicarakan, sebab makin banyak yang membagikan, makin akurat pula isinya","Peneliti & jurnalis independen, lembaga yang mengkaji dampak sosial, & beragam perspektif — dibanding hanya materi pemasaran perusahaan atau judul dramatis media","Hanya iklan dan siaran pers dari perusahaan AI yang membuatnya, sebab merekalah yang paling tahu dan pasti paling jujur tentang produknya"],answer:1,explain:"Perusahaan punya kepentingan mempromosikan produknya; media punya kepentingan menarik perhatian. Sumber independen & beragam memberi gambaran lebih seimbang.",hint:"Siapa yang punya kepentingan melebih-lebihkan (atau menakut-nakuti) tentang AI?"},
{n:87,type:"tf",micro:"Keterlibatan warga telah mengubah teknologi sebelumnya",q:"Benar atau Salah: Dalam sejarah, tekanan warga, jurnalisme, & advokasi telah memengaruhi aturan tentang teknologi (keselamatan mobil, obat, makanan, polusi) — jadi keterlibatan publik dalam mengarahkan AI juga bisa berarti.",answer:true,explain:"Aturan yang melindungi publik dari teknologi sering datang setelah tekanan masyarakat & bukti bahaya, bukan sukarela dari industri saja.",hint:"Dari mana datangnya aturan sabuk pengaman & label peringatan obat?"},
{n:88,type:"mcq",micro:"Menyeimbangkan pemanfaatan & kehati-hatian dalam hidupmu",q:"Untuk dirimu sendiri, keseimbangan yang sehat:",options:["Serahkan sebanyak mungkin ke AI","Tolak AI sepenuhnya","Manfaatkan AI untuk belajar & bekerja lebih baik, sambil menjaga keterampilan intimu terlatih, memverifikasi yang penting, melindungi data, & tetap yang bertanggung jawab atas keputusan & karyamu"],answer:2,explain:"Bukan 'pakai semua' atau 'tolak semua', melainkan memakai sebagai penguat sambil menjaga kapasitas & tanggung jawabmu sendiri.",hint:"Alat untuk memperkuatmu, dengan apa yang tetap harus kamu jaga sendiri?"},
{n:89,type:"mcq",micro:"Menghadapi ketidakpastian dengan tenang",q:"Cara mengelola kecemasan tentang masa depan AI:",options:["Fokus pada lingkaran pengaruhmu (keterampilan, kebiasaan, pilihan, suara), bangun kesiapan yang tahan berbagai skenario, & ikuti perkembangan tanpa terobsesi setiap berita","Cemas terus tentang skenario terburuk","Abaikan semuanya"],answer:0,explain:"Mengarahkan energi ke apa yang bisa kamu pengaruhi & membangun ketahanan mengurangi kecemasan & meningkatkan kesiapan nyata.",hint:"Apa yang bisa kamu kendalikan, & apa yang hanya bisa kamu pantau?"},
{n:90,type:"mcq",micro:"Menutup: batas & masa depan AI",q:"Sikap paling berguna:",options:["AI tidak penting dan tidak akan berubah banyak, sehingga kita tidak perlu mempelajarinya, memikirkan dampaknya, atau ikut terlibat mengarahkannya sama sekali","AI punya kemampuan nyata & keterbatasan nyata; masa depannya tidak pasti & dibentuk pilihan manusia; jadi kita belajar memahaminya, memakainya dengan bijak & bertanggung jawab, menjaga keterampilan & nilai kita, & terlibat dalam mengarahkannya untuk manfaat yang adil","AI akan menyelesaikan atau menghancurkan segalanya secara pasti, sehingga kita hanya penonton yang tidak bisa memengaruhi arah maupun hasil akhirnya sedikit pun"],answer:1,explain:"Realistis tentang kemampuan & batas, jujur tentang ketidakpastian, & aktif dalam pemakaian & pengarahan — itu inti kesiapan menghadapi AI.",hint:"Gabungkan: kemampuan & batas nyata + masa depan dibentuk pilihan + belajar, pakai bijak, jaga keterampilan, terlibat."},
{n:91,type:"mcq",micro:"Ringkasan: batas & masa depan AI",q:"Rangkuman paling tepat:",options:["AI sudah setara dengan manusia dalam segala hal dan masa depannya sudah pasti, sehingga kita tidak perlu lagi belajar, bersikap kritis, atau ikut menentukan arah penggunaannya sama sekali","AI hanyalah khayalan tanpa dampak nyata pada kehidupan siapa pun, sehingga semua pembahasan tentang bias, privasi, pekerjaan, dan keselamatan hanya kekhawatiran berlebihan yang tidak perlu diperhatikan","AI unggul pada pola & kecepatan tapi terbatas pada pengetahuan (data/waktu), keandalan (bisa keliru/halusinasi/tidak konsisten), akal sehat & konteks, tugas bernilai & fisik rumit, & keadilan bahasa; hampir semua AI masih 'sempit'; masa depannya (kemampuan, kecepatan, dampak pada pekerjaan, keselamatan, distribusi manfaat) tidak pasti & sangat dipengaruhi pilihan manusia; jadi respons yang tepat adalah literasi, keterampilan dasar yang kuat, pemakaian yang bijak & bertanggung jawab, sikap kritis terhadap hype & ketakutan berlebihan, & keterlibatan warga dalam mengarahkannya"],answer:2,explain:"Inti: kemampuan & batas nyata + masih sempit + masa depan tidak pasti & dibentuk manusia + respons berupa literasi, keterampilan, pemakaian bijak, sikap kritis, & keterlibatan.",hint:"Gabungkan: batas berlapis + masih sempit + masa depan dibentuk pilihan + respons aktif & seimbang."},
{n:92,type:"tf",micro:"Kesiapan menghadapi AI adalah kombinasi keterampilan & sikap",q:"Benar atau Salah: Menjadi siap menghadapi masa depan dengan AI cukup dengan menguasai satu keterampilan teknis spesifik, tanpa perlu menjaga keterampilan berpikir sendiri, sikap kritis, atau keterlibatan sebagai warga.",answer:false,explain:"Kesiapan bersifat menyeluruh: memahami AI, menjaga keterampilan berpikir & belajar sendiri, memakai AI dengan bijak & jujur, bersikap kritis terhadap klaim, & terlibat sebagai warga — bukan satu keterampilan teknis saja.",hint:"Apakah satu kursus coding cukup untuk 'siap menghadapi AI'?"},
{n:93,type:"mcq",micro:"Tiga prinsip praktis",q:"Tiga prinsip praktis menghadapi batas & masa depan AI:",options:["Kenali apa yang AI bisa & tidak bisa (& verifikasi yang penting); jaga keterampilan berpikir, belajar, & menilai milikmu sendiri; & bersikap kritis terhadap hype maupun ketakutan berlebihan sambil ikut membentuk arahnya","Percaya semua klaim yang kamu dengar tentang AI; serahkan semua pekerjaan kepadanya; dan jangan memikirkan masa depan karena semuanya akan baik-baik saja dengan sendirinya","Tolak AI sepenuhnya dalam keadaan apa pun; abaikan semua perkembangan terbaru; dan jangan terlibat dalam diskusi atau keputusan apa pun yang berkaitan dengan teknologi ini"],answer:0,explain:"Kenali batas & verifikasi + jaga keterampilan sendiri + sikap kritis & keterlibatan = inti menghadapi AI & masa depannya.",hint:"Gabungkan: kenali batas + jaga keterampilan + kritis & terlibat."},
{n:94,type:"open",micro:"Kapstone: memahami & menyikapi AI",q:"Tulis sebuah esai pendek (250–400 kata) berjudul 'AI: Apa yang Ia Bisa, Apa yang Tidak, & Bagaimana Kita Sebaiknya Menyikapinya'. Cakup: (1) apa yang AI lakukan dengan baik & mengapa (prediksi pola dari data), (2) minimal 4 keterbatasan nyata dengan alasannya, (3) mengapa masa depan AI tidak pasti & dibentuk oleh pilihan manusia, (4) risiko nyata yang sudah ada sekarang, (5) apa yang akan kamu lakukan secara pribadi, (6) apa yang perlu dilakukan masyarakat. Tunjukkan sikap seimbang — bukan kekaguman buta atau ketakutan lumpuh.",explain:"Kapstone menuntut sintesis menyeluruh: kemampuan berbasis pola, keterbatasan berlapis dengan alasan mekanistik, ketidakpastian masa depan & peran pilihan manusia, risiko nyata masa kini, tindakan pribadi konkret, & kebijakan sosial — semuanya dengan nada seimbang yang menahan manfaat, risiko, & ketidakpastian sekaligus.",hint:"Untuk tiap keterbatasan, sebutkan MENGAPA (prediksi pola bukan pemahaman, data tak tertulis, tanggung jawab manusia) — bukan hanya 'AI tidak bisa X'.",sample:"Esai baik: (1) menjelaskan bahwa AI modern belajar pola dari data dalam jumlah besar & memakainya untuk memprediksi/menghasilkan — kuat untuk bahasa, persepsi, & tugas berpola bervolume tinggi. (2) Menyebut keterbatasan dengan alasan: batas pengetahuan (data berhenti di titik waktu tertentu → bisa usang); keandalan/halusinasi (dilatih menghasilkan teks yang 'terdengar benar', bukan hanya fakta terverifikasi → perlu dicek); akal sehat & konteks (pengetahuan tak tertulis tentang dunia fisik/sosial jarang ada di data); keputusan bernilai (butuh empati, konteks, tanggung jawab manusia); tindakan fisik rumit (dunia nyata terlalu bervariasi); keadilan bahasa (kurang data → layanan lebih buruk untuk sebagian bahasa/budaya). (3) Menjelaskan bahwa laju & arah kemajuan tidak pasti (bisa cepat, melambat karena kendala, atau melompat), & bahwa pendanaan, penelitian, aturan, & tekanan publik membentuk hasilnya — bukan takdir. (4) Menyebut risiko sekarang: bias sistem, misinformasi & deepfake berskala, pelanggaran privasi, dampak pada pekerjaan, konsentrasi kekuasaan — bukan skenario fiksi ilmiah. (5) Rencana pribadi: menjaga keterampilan menulis/berhitung/berpikir kritis dengan berlatih sendiri; memakai AI untuk memahami & memeriksa, bukan menggantikan usaha; memverifikasi informasi penting; melindungi data; tidak menyebarkan yang belum diverifikasi. (6) Untuk masyarakat: aturan proporsional untuk pemakaian berisiko tinggi dengan transparansi, audit independen, & hak banding; investasi pendidikan & jaring pengaman untuk transisi pekerjaan; kerja sama internasional soal keamanan; & memastikan manfaat tersebar luas. Sikap keseluruhan: AI adalah alat kuat dengan potensi besar & risiko nyata; masa depannya bergantung pada apa yang kita pilih & lakukan sekarang."},
{n:95,type:"mcq",micro:"Menghindari dua kesalahan umum",q:"Dua kesalahan umum dalam menyikapi AI, & penawarnya:",options:["Tidak ada kesalahan umum sama sekali dalam menyikapi AI, sehingga siapa pun bebas bersikap apa saja tanpa perlu memperbaiki cara pandangnya terhadap teknologi ini","Melebih-lebihkan (dari demo viral & pemasaran) → cari data kegagalan & sumber independen. Menganggap remeh/menyangkal → perhatikan risiko nyata yang sudah berdampak & bersiap untuk perubahan","Kedua kesalahan itu sebenarnya benar, sehingga melebih-lebihkan maupun menyangkal sama-sama sikap yang tepat dan tidak perlu diperbaiki dengan cara apa pun"],answer:1,explain:"Hype & penyangkalan sama-sama mengaburkan gambaran akurat. Penawarnya adalah bukti yang menyeluruh & perhatian pada dampak nyata.",hint:"Apa yang membuat orang terlalu percaya, & apa yang membuat orang terlalu mengabaikan?"},
{n:96,type:"mcq",micro:"Nilai keterampilan manusia yang bertahan",q:"Keterampilan manusia yang kemungkinan tetap bernilai tinggi di masa depan dengan AI:",options:["Menghafal fakta dalam jumlah besar, karena kemampuan mengingat banyak informasi adalah hal yang tidak mungkin dikalahkan oleh AI di masa depan","Melakukan perhitungan aritmetika cepat di dalam kepala, sebab kecepatan berhitung manusia akan selalu lebih unggul daripada komputer dan AI","Berpikir kritis & menilai bukti, kreativitas berakar pengalaman, kecerdasan sosial & empati, kepemimpinan & etika, kemampuan belajar & beradaptasi, & mengajukan pertanyaan yang tepat"],answer:2,explain:"Keterampilan yang melengkapi AI (menilai, memimpin, berempati, mengarahkan, beradaptasi) cenderung lebih bernilai daripada yang mudah diotomasi.",hint:"Keterampilan apa yang justru makin dibutuhkan saat mesin bisa menghasilkan banyak output?"},
{n:97,type:"tf",micro:"Memahami AI membuat kita pengguna & warga yang lebih baik",q:"Benar atau Salah: Orang yang memahami kemampuan & keterbatasan AI cenderung memakainya lebih efektif & aman, lebih tahan terhadap hype & misinformasi, & lebih mampu ikut membentuk aturan yang baik — dibanding yang menganggapnya ajaib atau menakutkan.",answer:true,explain:"Literasi AI adalah keterampilan kewargaan: ia mengubah orang dari objek pasif teknologi menjadi peserta yang bisa memanfaatkan, melindungi diri, & menuntut perbaikan.",hint:"Pengguna yang paham alat vs yang menganggapnya sihir — siapa yang lebih berdaya?"},
{n:98,type:"mcq",micro:"Inti yang dibawa pulang",q:"Satu gagasan inti tentang batas & masa depan AI:",options:["AI adalah alat berbasis pola dengan kemampuan & keterbatasan yang nyata & spesifik; masa depannya belum ditulis & bergantung pada pilihan manusia; jadi tugas kita adalah memahaminya, memakainya dengan bijak, menjaga keterampilan & nilai kita, & ikut mengarahkannya untuk kebaikan bersama","AI akan menentukan masa depan sendirian tanpa campur tangan manusia, sehingga tugas kita hanyalah menunggu dan menerima apa pun yang diputuskan oleh teknologi itu","Masa depan AI sudah pasti dan sepenuhnya di luar kendali kita, jadi memahami, memilih cara memakai, dan ikut mengarahkannya tidak ada gunanya sama sekali"],answer:0,explain:"AI sebagai alat yang kuat namun terbatas, dengan masa depan yang dibentuk manusia — & respons berupa pemahaman, pemakaian bijak, penjagaan keterampilan, & keterlibatan.",hint:"Alat berbasis pola + batas nyata + masa depan dibentuk manusia + tugas kita apa?"},
{n:99,type:"mcq",micro:"Menghubungkan seluruh literasi AI",q:"Domain Literasi AI secara keseluruhan mengajarkan bahwa AI...",options:["Adalah topik yang tidak relevan bagi kebanyakan orang, sehingga anak-anak dan remaja tidak perlu mempelajarinya, memeriksa hasilnya, atau menjaga data pribadinya ketika memakai teknologi","Adalah program yang belajar pola dari data (dibuat & diarahkan manusia), dipakai luas dalam hidup sehari-hari, bisa keliru & bias, memengaruhi informasi & keputusan kita, memakai data kita, & masa depannya belum pasti — sehingga menuntut pemahaman, pemakaian yang bijak & jujur, kewaspadaan terhadap bias & misinformasi, penjagaan privasi & keterampilan, & keterlibatan warga","Adalah makhluk cerdas yang mengatur dirinya sendiri tanpa campur tangan manusia, punya kesadaran dan keinginannya sendiri, dan selalu benar sehingga tidak perlu diawasi oleh siapa pun"],answer:1,explain:"Benang merah seluruh domain: AI berbasis pola & dibuat manusia; meresap & berpengaruh; bisa keliru & bias; memakai data kita; masa depannya dibentuk pilihan — respons: paham, pakai bijak & jujur, waspada, lindungi, & terlibat.",hint:"Rangkum semua skill AI-01 sampai AI-08 dalam satu kalimat."},
{n:100,type:"open",micro:"Kapstone: rencana pribadi menghadapi era AI",q:"Tulis 'rencana pribadi menghadapi era AI' untuk 3 tahun ke depan. Cakup: (1) keterampilan dasar yang akan kamu jaga & kembangkan sendiri (& bagaimana), (2) cara kamu akan memakai AI sebagai alat bantu (untuk apa, dengan aturan verifikasi & privasi apa), (3) cara kamu akan tetap update tentang AI dengan sikap kritis (sumber apa), (4) satu kontribusi yang ingin kamu buat (mengajari orang lain, ikut diskusi, membuat sesuatu yang bermanfaat dengan AI secara bertanggung jawab), (5) nilai-nilai yang akan memandu keputusanmu tentang kapan & bagaimana memakai AI.",explain:"Kapstone menuntut rencana pribadi yang menghubungkan seluruh domain: menjaga keterampilan dasar dengan cara konkret, memakai AI sebagai alat dengan aturan verifikasi & privasi, tetap update dengan sikap kritis & sumber yang tepat, satu kontribusi nyata, & nilai-nilai eksplisit yang memandu keputusan — seimbang antara memanfaatkan & menjaga diri.",hint:"Setiap bagian harus konkret & bisa kamu mulai minggu ini; bagian (5) mengikat semuanya — nilai apa yang membuatmu memutuskan 'pakai AI di sini, tidak di sana'?",sample:"Rencana baik bersifat konkret & seimbang. Contoh unsur: (1) Keterampilan: menulis (menulis reflektif/argumen rutin tanpa AI, minta AI hanya untuk umpan balik setelah selesai); berpikir kritis & verifikasi (berlatih membedah klaim & mengecek sumber); satu keterampilan mendalam yang kunikmati (mis. menggambar/musik/coding) yang kulatih sendiri; belajar cara belajar (mencoba dulu, mencari pola, meninjau). (2) Pemakaian AI: untuk menjelaskan konsep yang kubingungkan, meringkas bacaan sebagai titik awal (lalu kubaca aslinya), brainstorming ide, & cek tata bahasa. Aturan: verifikasi setiap fakta/angka dengan 1 sumber tepercaya sebelum kupakai; tidak mengunggah data pribadi (milikku/orang lain) ke layanan tak jelas; tidak menyerahkan karya AI sebagai buatan sendiri di tugas/lomba; coba soal sendiri dulu sebelum tanya AI. (3) Update: mengikuti beberapa peneliti & jurnalis independen, membaca ringkasan dari lembaga yang mengkaji dampak sosial, & selalu bertanya 'siapa yang membuat klaim ini & apa kepentingannya' — bukan hanya judul viral. (4) Kontribusi: membantu adik kelas & keluarga mengenali penipuan & konten AI, & mengajari cara mengecek informasi; mungkin membuat proyek kecil yang bermanfaat (mis. panduan belajar) dengan bantuan AI secara transparan. (5) Nilai: kejujuran (jujur soal pemakaian AI & tidak menyesatkan orang); pertumbuhan (tidak menyerahkan usaha yang melatihku); menghormati orang lain (privasi & martabat mereka dalam apa pun yang kubuat); tanggung jawab (aku bertanggung jawab atas apa yang kuhasilkan & bagikan); & keberanian untuk berbeda (memakai AI lebih sedikit bila itu selaras dengan tujuan belajarku, meski orang lain memakai lebih banyak)."},
];
